<script setup>import BaseModal from './BaseModal.vue';defineProps({open:Boolean,title:String,message:String,busy:Boolean,error:String,busyText:{type:String,default:'Processant…'}});defineEmits(['cancel','confirm'])</script>
<template><BaseModal :open="open" :title="title" :closeable="!busy" @close="$emit('cancel')"><p>{{message}}</p><div v-if="busy" class="processing-message" role="status" aria-live="polite"><span class="spinner"></span><div><strong>{{busyText}}</strong><small>No tanqueu aquesta finestra. L’operació pot trigar uns moments.</small></div></div><div v-if="error" class="alert error" role="alert">{{error}}</div><template #actions><button class="button secondary" :disabled="busy" @click="$emit('cancel')">Cancel·lar</button><button class="button danger" :disabled="busy" @click="$emit('confirm')"><span v-if="busy" class="spinner button-spinner"></span>{{busy?busyText:'Confirmar'}}</button></template></BaseModal></template>
